const keys=Object.keys(phrases).sort((a,b)=>b.length-a.length);
function annotate(text){const frag=document.createDocumentFragment();for(let i=0;i<text.length;){let key=keys.find(k=>text.startsWith(k,i));let word=key||text[i], sounds=key?phrases[key].split(' '):[dict[word]];[...word].forEach((ch,j)=>{if(sounds[j]){const el=document.createElement('span');el.className='zy-char';el.dataset.sound=sounds[j];el.textContent=ch;frag.appendChild(el)}else frag.appendChild(document.createTextNode(ch))});i+=word.length}return frag}
function process(root){if(root.nodeType===3){const parent=root.parentElement;if(!parent||parent.closest('script,style,textarea,option,select,svg,math,.zy-char,.zy-mirror,[contenteditable]')||!/[\u3400-\u9fff]/.test(root.nodeValue))return;root.replaceWith(annotate(root.nodeValue));return}if(root.nodeType!==1&&root.nodeType!==9)return;if(root.nodeType===1&&root.closest('script,style,textarea,option,select,svg,math,.zy-char,.zy-mirror,[contenteditable]'))return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let list=[],n;while(n=walker.nextNode())list.push(n);list.forEach(process)}
